#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>
#include <linux/rfcomm/core.h>
#include <linux/rfcomm/tty.h>
#include <linux/rfcomm/sock.h>

int rfcomm_get_dev_list(void __user *arg)
{
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list __user *ulist;
    struct rfcomm_dev_list list;
    int i = 0, rc = -EFAULT;
    int count;

    if (get_user(count, (int __user *)arg))
        return -EFAULT;

    if (count <= 0)
        return -EINVAL;

    ulist = arg;
    list = kmalloc(count * sizeof(struct rfcomm_dev), GFP_KERNEL);
    if (!list)
        return -ENOMEM;

    mutex_lock(&rfcomm_dev_lock);

    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (i >= count)
            break;

        if (dev->flags & RFCOMM_DEV_REleased)
            continue;

        list[i].id = dev->id;
        list[i].flags = dev->flags;
        list[i].state = dev->state;
        list[i].line = dev->line;
        list[i].port = dev->port;
        list[i].owner = dev->owner;

        i++;
    }

    mutex_unlock(&rfcomm_dev_lock);

    if (copy_to_user(ulist, list, i * sizeof(struct rfcomm_dev))) {
        kfree(list);
        return -EFAULT;
    }

    kfree(list);
    return 0;
}

int get_rfcomm_device_list(void __user *arg) {
    int num_devices;
    struct rfcomm_dev_list *dev_list = NULL;
    struct rfcomm_dev *d;
    int i = 0;

    if (get_user(num_devices, (int __user *)arg))
        return -EFAULT;

    if (num_devices <= 0)
        return -EINVAL;

    dev_list = kmalloc(sizeof(struct rfcomm_dev_list) + num_devices * sizeof(struct rfcomm_dev_entry), GFP_KERNEL);
    if (!dev_list)
        return -ENOMEM;

    dev_list->count = 0;

    mutex_lock(&rfcomm_dev_list_mutex);

    list_for_each_entry(d, &rfcomm_dev_list, list) {
        if (i >= num_devices)
            break;
        if (!test_bit(RFCOMM_DEV_REGISTERED, &d->flags))
            continue;
        dev_list->entry[i].id = d->id;
        dev_list->entry[i].flags = d->flags;
        dev_list->count++;
        i++;
    }

    mutex_unlock(&rfcomm_dev_list_mutex);

    if (copy_to_user(arg, dev_list, sizeof(struct rfcomm_dev_list) + dev_list->count * sizeof(struct rfcomm_dev_entry))) {
        kfree(dev_list);
        return -EFAULT;
    }

    kfree(dev_list);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>
#include <linux/mutex.h>

int get_rfcomm_devices(void __user *arg) {
    int err = 0;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_info *info;
    unsigned int count, i = 0;
    struct rfcomm_dev_list list;

    if (get_user(count, (unsigned int __user *)arg))
        return -EFAULT;

    if (!count)
        return 0;

    info = kzalloc(count * sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    mutex_lock(&rfcomm_dev_list_mutex);

    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (i >= count)
            break;
        if (dev->flags & RFCOMM_DEV_RELEASED)
            continue;

        info[i].id = dev->id;
        info[i].state = dev->state;
        info[i].channel = dev->channel;
        i++;
    }

    mutex_unlock(&rfcomm_dev_list_mutex);

    if (copy_to_user(arg, info, count * sizeof(*info))) {
        err = -EFAULT;
    }

    kfree(info);
    return err ? err : 0;
}

int get_rfcomm_devices(void __user *arg) {
    int num_devices;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list *list;
    int i = 0;

    if (get_user(num_devices, (int __user *)arg))
        return -EFAULT;

    if (num_devices <= 0)
        return -EINVAL;

    list = kmalloc(sizeof(struct rfcomm_dev_list) + num_devices * sizeof(struct rfcomm_dev), GFP_KERNEL);
    if (!list)
        return -ENOMEM;

    list->count = 0;

    lock_device_list();
    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (i >= num_devices)
            break;

        if (!dev->released) {
            list->devices[i++] = *dev;
            list->count++;
        }
    }
    unlock_device_list();

    if (copy_to_user(arg, list, sizeof(struct rfcomm_dev_list) + list->count * sizeof(struct rfcomm_dev))) {
        kfree(list);
        return -EFAULT;
    }

    kfree(list);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>

int rfcomm_dev_list_get(void __user *arg)
{
    int num_devs, i;
    struct rfcomm_dev *d;
    struct rfcomm_dev_list *list;

    if (get_user(num_devs, (int __user *)arg))
        return -EFAULT;

    if (num_devs <= 0)
        return -EINVAL;

    list = kzalloc(sizeof(*list) + num_devs * sizeof(list->dev[0]), GFP_KERNEL);
    if (!list)
        return -ENOMEM;

    mutex_lock(&rfcomm_dev_list_lock);

    list->count = 0;
    list_for_each_entry(d, &rfcomm_dev_list, list) {
        if (list->count >= num_devs)
            break;
        if (d->sentinel || d->release)
            continue;

        list->dev[list->count].id = d->id;
        list->dev[list->count].state = d->state;
        list->dev[list->count].type = d->type;
        list->dev[list->count].mtu = d->mtu;
        list->dev[list->count].features = d->features;
        list->count++;
    }

    mutex_unlock(&rfcomm_dev_list_lock);

    if (copy_to_user(arg, list, sizeof(*list) + list->count * sizeof(list->dev[0]))) {
        kfree(list);
        return -EFAULT;
    }

    kfree(list);
    return 0;
}
